class ClassesScreen extends ConsumerStatefulWidget { const ClassesScreen({super.key}); @override ConsumerState<ClassesScreen> createState()=>_ClassesScreenState(); }
class _ClassesScreenState extends ConsumerState<ClassesScreen>{
  Future<void> _addCycle() async {final c=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Ajouter un cycle'),content:TextField(controller:c,autofocus:true,decoration:const InputDecoration(labelText:'Nom du cycle')),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(x,c.text.trim().isNotEmpty),child:const Text('Ajouter'))]));if(ok==true){try{await ref.read(settingsRepositoryProvider).addCycle(name:c.text);ref.invalidate(cyclesProvider);if(mounted)setState((){});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
