mer'))])));}
  Future<void> _addClass() async {final repo=ref.read(settingsRepositoryProvider);final cycles=await repo.cycles();if(!mounted||cycles.isEmpty)return;final name=TextEditingController(),capacity=TextEditingController();String cycleId=cycles.first['id'] as String;final saved=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,setM)=>AlertDialog(title:const Text('Ajouter une classe'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:cycleId,decoration:const InputDecoration(labelText:'Cycle'),items:cycles.map((c)=>DropdownMenuItem(value:c['id'] as String,child:Text(c['name'] as String))).toList(),onChanged:(v)=>v==null?null:setM(()=>cycleId=v)),const SizedBox(height:10),TextField(controller:name,decoration:const InputDecoration(labelText:'Nom')),const SizedBox(height:10),TextField(controller:capacity,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Capacité'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(context,name.text.trim().isNotEmpty),child:const Text('Ajouter'))])));if(saved==true){try{await repo.addClassroom(cycleId:cycleId,name:name.text,capacity:int.tryParse(capacity.text));ref.invalidate(classroomsProvider);ref.invalidate(allClassroomsProvider);ref.invalidate(auditEntriesProvider);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
  Future<void> _edit(dynamic item) async {final name=TextEditingController(text:item.name),capacity=TextEditingController(text:item.capacity?.toString()??'');bool active=item.active;final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setM)=>AlertDialog(title:const Text('Modifier la classe'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Nom')),const SizedBox(height:10),TextField(controller:capacity,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Capacité')),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Classe active'),value:active,onChanged:(v)=>setM(()=>active=v))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Enregistrer'))])));if(ok==true){try{await ref.read(settingsRepositoryProvider).updateClassroom(id:item.id,name:name.text,capacity:int.tryParse(capacity.text),active:active);ref.invalidate(classroomsProvider);ref.invalidate(allClassroomsProvider);ref.invalidate(auditEntriesProvider);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
  @override Widget build(BuildContext context){final classrooms=ref.watch(allClassroomsProvider);return Scaffold(appBar:AppBar(title:const Text('Cycles et classes'),actions:[if(!OperatorSession.isReadOnly)...[IconButton(tooltip:'Gérer les cycles',onPressed:_manageCycles,icon:const Icon(Icons.tune)),IconButton(tooltip:'Ajouter un cycle',onPressed:_addCycle,icon:const Icon(Icons.account_tree_outlined))]]),floatingActionButton:OperatorSession.isReadOnly?null:FloatingActionButton.extended(onPressed:_addClass,icon:const Icon(Icons.add),label:const Text('Classe')),body:classrooms.when(data:(items)=>items.isEmpty?const Center(child:Text('Aucune classe.')):ListView.separated(padding:const EdgeInsets.all(16).copyWith(bottom:96),itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i)=>Card(child:ListTile(leading:const Icon(Icons.meeting_room_outlined),title:Text(items[i].name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${items[i].cycleName} · ${items[i].occupancyLabel}${items[i].active ? '' : ' · désactivée'}'),trailing:OperatorSession.isReadOnly?null:const Icon(Icons.edit_outlined),onTap:OperatorSession.isReadOnly?null:()=>_edit(items[i])))),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('Erreur : $e'))));}}
